    5| import type { DegradationNotice, PersistedWorkflowState, WorkflowState } from "./types.js"
    6| 
    7| const stateFileName = "workflow-state.json"
    8| 
    9| export interface WorkflowStateLoadResult {
   10|   readonly state: WorkflowState | undefined
   11|   readonly degradations: readonly DegradationNotice[]
   12| }
   13| 
   14| export interface WorkflowStateStore {
   15|   readonly load: () => Promise<WorkflowStateLoadResult>
   16|   readonly update: (state: WorkflowState) => Promise<void>
   17|   /**
   18|    * Loads, changes, and writes the state as one step. Mutations of the same state file are
   19|    * serialized within the process, so concurrent hooks and tools cannot drop each other's
   20|    * changes. Returning undefined leaves the state unchanged.
   21|    */
   22|   readonly mutate: (change: (state: WorkflowState) => WorkflowState | undefined) => Promise<WorkflowState | undefined>
   23|   readonly clear: () => Promise<void>
   24| }
   25| 
   26| // One queue per state file and process: every plugin instance and tool shares it.
   27| const mutationQueues: Map<string, Promise<unknown>> = ((globalThis as Record<symbol, unknown>)[Symbol.for("open-ultracode.state-queues")] ??= new Map<string, Promise<unknown>>()) as Map<string, Promise<unknown>>
   28| 
   29| export interface WorkflowStateStoreConfig {
   30|   readonly state: {
   31|     readonly directory: string
   32|   }
   33| }
   34| 
   35| export function createWorkflowStateStore(
   36|   projectRoot: string,
   37|   config: WorkflowStateStoreConfig
   38| ): WorkflowStateStore {
   39|   const root = resolve(projectRoot)
   40|   const statePath = resolveStatePath(projectRoot, config.state.directory)
   41| 
   42|   const store: WorkflowStateStore = {
   43|     async load(): Promise<WorkflowStateLoadResult> {
   44|       await rejectSymlinkedStatePath(root, config.state.directory, statePath)
   45| 
   46|       let raw: string
   47|       try {
   48|         raw = await retryTransient(() => readFile(statePath, "utf8"))
   49|       } catch (error) {
   50|         if (isNodeError(error) && error.code === "ENOENT") {
   51|           return { state: undefined, degradations: [] }
   52|         }
   53|         // I/O errors are not corruption: never move a valid but busy state file aside.
   54|         throw error
   55|       }
   56| 
   57|       let parsed: unknown
   58|       try {
   59|         parsed = JSON.parse(raw)
   60|       } catch (error) {
   61|         return backupCorrupt(error)
   62|       }
   63|       if (!isPersistedWorkflowState(parsed)) {
   64|         return backupCorrupt(new Error("state file did not match the expected schema"))
   65|       }
   66| 
   67|       return { state: parsed.state, degradations: [] }
   68|     },
   69| 
   70|     mutate(change) {
   71|       const previous = mutationQueues.get(statePath) ?? Promise.resolve()
   72|       const next = previous.catch(() => {}).then(async () => {
   73|         const { state } = await store.load()
   74|         if (state === undefined) return undefined
   75|         const changed = change(state)
   76|         if (changed === undefined) return state
   77|         await store.update(changed)
   78|         return changed
   79|       })
   80|       mutationQueues.set(statePath, next)
   81|       void next.finally(() => {
   82|         if (mutationQueues.get(statePath) === next) mutationQueues.delete(statePath)
   83|       }).catch(() => {})
   84|       return next
   85|     },
   86| 
   87|     async update(state: WorkflowState): Promise<void> {
   88|       await rejectSymlinkedStatePath(root, config.state.directory, statePath)
   89|       await mkdir(dirname(statePath), { recursive: true })
   90|       await rejectSymlinkedStatePath(root, config.state.directory, statePath)
   91|       const persisted: PersistedWorkflowState = {
   92|         schemaVersion: 1,
   93|         updatedAt: state.updatedAt,
   94|         state
   95|       }
   96|       await writeStateAtomically(statePath, `${JSON.stringify(persisted, null, 2)}\n`)
   97|     },
   98| 
   99|     async clear(): Promise<void> {
  100|       await rejectSymlinkedStatePath(root, config.state.directory, statePath)
  101|       await rm(statePath, { force: true })
  102|     }
  103|   }
  104| 
  105|   async function backupCorrupt(error: unknown): Promise<WorkflowStateLoadResult> {
  106|     await backupCorruptState(statePath)
  107|     return { state: undefined, degradations: [createCorruptStateNotice(error)] }
  108|   }
  109| 
  110|   return store
  111| }
