  113| const transientErrorCodes = new Set(["EPERM", "EACCES", "EBUSY"])
  114| 
  115| /**
  116|  * Windows reports EPERM/EACCES/EBUSY while another handle (a concurrent read, an indexer,
  117|  * antivirus) holds the file; the operation succeeds a few milliseconds later.
  118|  */
  119| async function retryTransient<T>(operation: () => Promise<T>, attempts = 8): Promise<T> {
  120|   for (let attempt = 1; ; attempt += 1) {
  121|     try {
  122|       return await operation()
  123|     } catch (error) {
  124|       if (attempt >= attempts || !isNodeError(error) || error.code === undefined || !transientErrorCodes.has(error.code)) throw error
  125|       await new Promise((resolve) => setTimeout(resolve, 5 * attempt))
  126|     }
  127|   }
  128| }
