  130| async function writeStateAtomically(statePath: string, contents: string): Promise<void> {
  131|   const stateDirectory = dirname(statePath)
  132|   const stagingDirectory = await mkdtemp(resolve(stateDirectory, `.workflow-state-write-${randomUUID()}-`))
  133|   const stagingPath = resolve(stagingDirectory, stateFileName)
  134| 
  135|   try {
  136|     await writeFile(stagingPath, contents, { encoding: "utf8", flag: "wx" })
  137|     await retryTransient(() => rename(stagingPath, statePath))
  138|   } finally {
  139|     await rm(stagingDirectory, { force: true, recursive: true })
  140|   }
  141| }
