  143| function resolveStatePath(projectRoot: string, stateDirectory: string): string {
  144|   if (!isSafeProjectRelativePath(stateDirectory)) {
  145|     throw new Error("state.directory must be a project-relative path and must not contain '..' segments or backslashes")
  146|   }
  147| 
  148|   const root = resolve(projectRoot)
  149|   const statePath = resolve(root, stateDirectory, stateFileName)
  150| 
  151|   if (statePath !== root && !statePath.startsWith(`${root}${sep}`)) {
  152|     throw new Error("state.directory must resolve inside the project root")
  153|   }
  154| 
  155|   return statePath
  156| }
  157| 
  158| function isSafeProjectRelativePath(value: string): boolean {
  159|   if (value.length === 0 || value.startsWith("/") || value.includes("\\")) {
  160|     return false
  161|   }
  162| 
  163|   return !value.split("/").includes("..")
  164| }
