  166| async function rejectSymlinkedStatePath(root: string, stateDirectory: string, statePath: string): Promise<void> {
  167|   let current = root
  168| 
  169|   for (const segment of stateDirectory.split("/")) {
  170|     current = resolve(current, segment)
  171| 
  172|     try {
  173|       const stats = await lstat(current)
  174|       if (stats.isSymbolicLink()) {
  175|         throw new Error("state.directory must not contain symlinks")
  176|       }
  177|     } catch (error) {
  178|       if (isNodeError(error) && error.code === "ENOENT") {
  179|         return
  180|       }
  181| 
  182|       throw error
  183|     }
  184|   }
  185| 
  186|   try {
  187|     const stats = await lstat(statePath)
  188|     if (stats.isSymbolicLink()) {
  189|       throw new Error("state.directory must not contain symlinks")
  190|     }
  191|   } catch (error) {
  192|     if (!isNodeError(error) || error.code !== "ENOENT") {
  193|       throw error
  194|     }
  195|   }
  196| }
  197| 
  198| async function backupCorruptState(statePath: string): Promise<void> {
  199|   try {
  200|     await retryTransient(() => rename(statePath, `${statePath}.bak`))
  201|   } catch (error) {
  202|     if (!isNodeError(error) || error.code !== "ENOENT") {
  203|       throw error
  204|     }
  205|   }
  206| }
  207| 
  208| function createCorruptStateNotice(error: unknown): DegradationNotice {
  209|   const reason = error instanceof Error ? error.message : "State file could not be read."
  210| 
  211|   return {
  212|     id: "workflow-state-corrupt",
  213|     capability: "workflow state persistence",
  214|     severity: "warning",
  215|     reason,
  216|     userVisibleMessage: "The OpenUltraCode workflow state file was corrupt and has been ignored for safety.",
  217|     safeNextAction: "Continue with a new workflow state; inspect workflow-state.json.bak if prior context is needed.",
  218|     occurredAt: new Date().toISOString()
  219|   }
  220| }
  221| 
  222| function isPersistedWorkflowState(value: unknown): value is PersistedWorkflowState {
  223|   if (!isRecord(value) || value.schemaVersion !== 1 || typeof value.updatedAt !== "string") {
  224|     return false
  225|   }
  226| 
  227|   const state = value.state
  228| 
  229|   return isRecord(state) && state.schemaVersion === 1 && typeof state.mode === "string" && typeof state.phase === "string"
  230| }
  231| 
  232| function isRecord(value: unknown): value is Record<string, unknown> {
  233|   return typeof value === "object" && value !== null && !Array.isArray(value)
  234| }
  235| 
  236| function isNodeError(error: unknown): error is NodeJS.ErrnoException {
  237|   return error instanceof Error && "code" in error
  238| }
